308: func (s *Source) scanTarget(ctx context.Context, client *gitlab.Client, target sources.ChunkingTarget, chunksChan chan *sources.Chunk) error {
309: 	metaType, ok := target.QueryCriteria.GetData().(*source_metadatapb.MetaData_Gitlab)
310: 	if !ok {
311: 		return fmt.Errorf("unable to cast metadata type for targeted scan")
312: 	}
313: 	meta := metaType.Gitlab
314: 	projID, sha := int(meta.GetProjectId()), meta.GetCommit()
315: 	if projID == 0 || sha == "" {
316: 		return fmt.Errorf("project ID and commit SHA must be provided for targeted scan")
317: 	}
318: 
319: 	aCtx := context.WithValues(ctx, "project_id", projID, "commit", sha)
320: 
321: 	diffs, _, err := client.Commits.GetCommitDiff(projID, sha, new(gitlab.GetCommitDiffOptions), gitlab.WithContext(ctx))
322: 	if err != nil {
323: 		return fmt.Errorf("error fetching diffs for commit %s: %w", sha, err)
324: 	}
325: 
326: 	for _, diff := range diffs {
327: 		if diff.Diff == "" {
328: 			aCtx.Logger().V(4).Info("skipping empty diff", "file", diff.NewPath)
329: 			continue
330: 		}
331: 
332: 		chunk := &sources.Chunk{
333: 			SourceType: s.Type(),
334: 			SourceName: s.name,
335: 			SourceID:   s.SourceID(),
336: 			JobID:      s.JobID(),
337: 			SecretID:   target.SecretID,
338: 			Data:       []byte(diff.Diff),
339: 			SourceMetadata: &source_metadatapb.MetaData{
340: 				Data: &source_metadatapb.MetaData_Gitlab{Gitlab: meta},
341: 			},
342: 			Verify: s.verify,
343: 		}
344: 
345: 		if err := common.CancellableWrite(ctx, chunksChan, chunk); err != nil {
346: 			return err
347: 		}
348: 	}
349: 
350: 	return nil
351: }
